{
  "probability": 0.95,
  "range_low": 0.90,
  "range_high": 0.98,
  "summary": [
    "Polls show the TISZA challenger often ahead or competitive, elevating the chance of a major seat tally.",
    "Two-thirds majority is historically achievable under Hungary's post-2011 system, providing a meaningful but not guaranteed baseline.",
    "Structural factors such as winner-takes-most seat amplification and potential district gerrymandering favor the leading bloc when conditions align.",
    "Persistent uncertainty remains due to polling divergence, the entry of Our Homeland Movement, and macro/political dynamics."
  ],
  "confidence": "high",
  "narrative": "Starting from a historical base where large majorities have occurred under Hungary's system, recent dynamics—especially opposition consolidation around TISZA and structural seat amplification—shift the probability toward a 2/3 outcome. While polling divergence and new party entries introduce uncertainty, the combination of strong structural incentives and favorable conditions yields a calibrated, high-probability estimate.",
  "justification": {
    "anchor": {
      "probability": 0.60,
      "basis": "Reference class: post-2011 Hungarian National Assembly elections under the 199-seat system (and earlier under the 386-seat system) where the ruling party or its alliance achieved a two-thirds majority in multiple elections. This provides a baseline expectation for 2/3 outcomes in 2026 and informs the anchor."
    },
    "factor_updates": [
      {
        "factor": "Opposition consolidation behind TISZA",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Unified anti-Orbán voting can increase the leading bloc's seat count, improving chances of reaching 133+ seats if turnout cooperates."
      },
      {
        "factor": "Electoral system amplifies leading bloc's seat share (winner-compensation)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Hungary's winner-compensation mechanism historically translates lead-vote shares into outsized seat shares, raising the probability of a 2/3 majority when the leading bloc is ahead."
      },
      {
        "factor": "Gerrymandering and district-level manipulation favoring incumbents",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "District maps and local-race strategies can magnify the leading bloc's seat tally, increasing odds of 133+ seats even with imperfect national majorities."
      },
      {
        "factor": "Turnout dynamics and undecided voters",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Shifts in turnout and undecided coalitions could tilt seat allocations toward the leading bloc if undecideds cohere in its favor."
      },
      {
        "factor": "Entry of Our Homeland Movement into Parliament",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Additional fragmentation could complicate math for a single bloc achieving 2/3, reducing odds unless vote shares still cohere around a dominant camp."
      },
      {
        "factor": "Macroeconomic headwinds and pre-election spending benefiting opposition",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Economic concerns and counter-campaign spending could erode incumbents' support, aiding a shift toward a larger bloc."
      },
      {
        "factor": "Market expectations of regime change and currency response",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Financial-market pricing of potential regime change signals heightened political risk resilience for the opposition, supporting a higher seat-share probability for a sizable bloc."
      }
    ],
    "synthesis_rationale": "Starting with a mid-range anchor based on historical frequency of 2/3 outcomes, the combination of strong structural amplification (strong upward pushes from factors 2 and 3) and supportive political dynamics (factors 1, 4, 6, and 7) outweigh negative impulses from factor 5 and ongoing polling variability. While correlated effects modestly inflate the confidence in a high-posterior estimate, residual uncertainty from turnout behavior and market noise justifies a calibrated probability of 0.95 with a range extending toward 0.90–0.98."
  }
}

{
