  "range_high": 0.98,
  "summary": [
    "Opposition consolidation behind TISZA and poll momentum raise the odds of a large-bloc seat share, potentially achieving 133+ seats.",
    "Electoral-system mechanics in Hungary amplify the leading bloc's seat count via winner-compensation, increasing the probability of a 2/3 majority when one bloc leads in votes.",
    "Gerrymandering and district-level biases favor incumbents, providing structural support for a 2/3 outcome under favorable conditions.",
    "Turnout dynamics and undecided-voter volatility introduce meaningful uncertainty, and market signals about regime change add conditional upside, but with caveats."
  ],
  "confidence": "high",
  "narrative": "Anchored in Hungary’s post-2011 electoral history where 2/3 majorities have occurred, updates from opposition consolidation, seat-amplification, and district bias push the probability toward a 2/3 outcome. While turnout and market dynamics create uncertainty, the aggregate signal yields a high posterior probability (~95%) of a supermajority for some bloc in 2026, within a relatively narrow credible interval.",
  "justification": {
    "anchor": {
      "probability": 0.65,
      "basis": "Two-thirds majorities have historically occurred in Hungary’s post-2011 system (2010, 2014, 2018, 2022) with Fidesz–KDNP achieving 2/3; the anchor reflects a mid-point within that historical base-rate and serves as a reasonable starting point for updating."
    },
    "factor_updates": [
      {
        "factor": "Opposition consolidation behind TISZA",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "FT and other outlets describe opposition unification around a single challenger, which could lift seat gains enough to approach 2/3 in aggregate."
      },
      {
        "factor": "Electoral system amplifies leading bloc's seat share (winner compensation)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Past analyses show the Hungarian mechanism translates top-line vote leads into outsized seat advantages, elevating 2/3 odds when a bloc leads in votes."
      },
      {
        "factor": "Gerrymandering and district-level manipulation favoring incumbents",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Evidence of district maps and local-race advantages helps translate vote-shares into seat shares for the incumbents, increasing 2/3 probability under favorable conditions."
      },
      {
        "factor": "Polling divergence and market signals indicating uncertainty",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Divergent polls and mixed betting-market signals reduce certainty about the path to 2/3, tempering the strength of the anchor update."
      },
      {
        "factor": "Turnout dynamics and undecided voters",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Turnout volatility and undecideds could tilt seat outcomes away from a clean 2/3 result, introducing downside risk to the leading bloc’s bid."
      },
      {
        "factor": "Market expectations of regime change (macro signaling)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Signals of possible regime change could bolster anti-incumbent sentiment, modestly lifting 2/3 odds via improved coalition prospects or stronger opposition performance."
      }
    ],
    "synthesis_rationale": "I start from a mid-baseline anchor reflecting historical 2/3 occurrences under Hungary’s post-2011 system. The updates collectively push probability upward due to structural amplification and potential opposition consolidation, while polling divergence, turnout uncertainty, and new-party dynamics inject downward pressure and residual uncertainty. Given the correlation among factors (e.g., opposition consolidation and electoral amplification both inflating seat shares), the posterior probability is calibrated toward 0.95, with a narrow but non-zero uncertainty range. The range accounts for potential overlaps among factors and the possibility that some updates double-count effects."
  }
}

